// OpenMod Flight Recorder · MIT
// Retain metadata only. Never keep arguments or output.
const LIMIT = 300;
let rows = [];
let sequence = 0;

export function register(on) {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'flight-recorder',
      description: 'Show tool timing metadata',
      argumentHint: '[json|clear]'
    });
    return next(e);
  });

  on('tool.call', async ($, e, next) => {
    const startedAt = await $.clock.now();
    const row = {
      id: ++sequence, tool: e.tool, startedAt,
      durationMs: 0, status: 'running'
    };
    rows.push(row);
    rows = rows.slice(-LIMIT);
    $.ui.invalidate('ui.render');
    try {
      const result = await next(e);
      row.status = result.deny !== undefined
        ? 'denied' : result.isError ? 'error' : 'ok';
      return result;
    } catch (error) {
      row.status = next.signal.aborted ? 'aborted' : 'error';
      throw error;
    } finally {
      row.durationMs = Math.max(0,
        (await $.clock.now()) - startedAt);
      $.ui.invalidate('ui.render');
    }
  });

  on('command.run', { command: 'flight-recorder' }, ($, e) => {
    if (e.args.trim() === 'clear') {
      rows = [];
      $.ui.invalidate('ui.render');
      return { text: 'Flight Recorder cleared.' };
    }
    if (e.args.trim() === 'json') {
      return { text: JSON.stringify({
        format: 'openmod-flight-recorder', version: 1,
        privacy: 'tool names, timestamps and outcomes only',
        events: rows
      }, null, 2) };
    }
    return { text: rows.length
      ? rows.map(r => r.id + '. ' + r.tool + ' · '
          + r.status + ' · ' + r.durationMs + 'ms').join('\n')
      : 'No tool calls yet.' };
  });

  on('ui.render', { component: 'AbovePrompt' }, ($, e, next) => {
    if (e.props.hasSurvey || !rows.length) return next(e);
    const { Box, Text } = $.ui.resolve(e);
    const last = rows[rows.length - 1];
    const issues = rows.filter(r =>
      r.status === 'error' || r.status === 'denied').length;
    return Box({ paddingX: 1, children: [
      Text({ color: issues ? 'yellow' : 'cyan',
        children: 'Flight Recorder · ' + rows.length
          + ' retained calls · ' + issues + ' issues' }),
      Text({ dimColor: true,
        children: 'Latest: ' + last.tool + ' ' + last.status
          + ' · ' + last.durationMs + 'ms · /flight-recorder' })
    ] });
  });
}

